# Look at ALL message types to find where the evaluator sends content
import os, re, json

d = os.environ.get('RLM_SESSION_DIR', '')
basename = os.path.basename(d)
jsonl_path = d + '/../../sessions/' + basename + '.jsonl'

with open(jsonl_path, 'r') as f:
    content = f.read()

lines = content.split('\n')

print("Message types found in session:")
type_counts = {}
for line in lines:
    if line.strip():
        try:
            obj = json.loads(line)
            msg_type = obj.get('type', 'unknown')
            type_counts[msg_type] = type_counts.get(msg_type, 0) + 1
        except:
            pass

for msg_type, count in sorted(type_counts.items()):
    print(f"  {msg_type}: {count}")

# Check if there are other user-like messages
print("\n--- Message roles ---")
for i, line in enumerate(lines):
    if line.strip():
        try:
            obj = json.loads(line)
            role = obj.get('message', {}).get('role', 'N/A')
            msg_type = obj.get('type', 'N/A')
            if role not in ('N/A', 'thinking', ''):
                print(f"Line {i}: type={msg_type}, role={role}")
                if i < 10:  # First 10 for context
                    print(f"  {obj}")
                    break
        except:
            pass

